**What works as claimed — use this for stderr + env:**

```ts
import { StdioClientTransport, getDefaultEnvironment } from '@modelcontextprotocol/sdk/client/stdio.js';

const transport = new StdioClientTransport({
  command: 'node',
  args: ['server.js'],
  stderr: 'pipe',                                  // string literal; IOType | Stream | number
  env: { ...getDefaultEnvironment(), MY_TOKEN: t } // MUST spread; see gotcha on env replacement
});

// transport.stderr is a live PassThrough HERE, before start()/connect().
// Attach the listener now — this is the ordering that avoids losing boot output.
transport.stderr!.on('data', c => logger.warn({ upstream }, String(c)));

await client.connect(transport);   // calls start() internally
transport.pid;                     // number — only non-null AFTER connect/start
```

**What does NOT work — the fallback, executed and passing (`spike-3b-subclass.mjs`).** Subclass and override only `start()` and `close()`; everything else (`send`, `stderr`, `pid`, `processReadBuffer`, `ReadBuffer` framing) is inherited:

```ts
import { spawn } from 'node:child_process';
import { StdioClientTransport, getDefaultEnvironment } from '@modelcontextprotocol/sdk/client/stdio.js';

// TS `private` is compile-time only; these fields are plain properties at runtime.
// Cast to any (or re-declare) to touch _process/_readBuffer/_serverParams/_stderrStream.
export class GroupStdioTransport extends StdioClientTransport {
  start(): Promise<void> {
    const self = this as any;
    if (self._process) throw new Error('already started');
    return new Promise((resolve, reject) => {
      self._process = spawn(self._serverParams.command, self._serverParams.args ?? [], {
        env: { ...getDefaultEnvironment(), ...self._serverParams.env },
        stdio: ['pipe', 'pipe', self._serverParams.stderr ?? 'inherit'],
        shell: false,
        detached: true,            // <- the whole point: child leads its own process group
        cwd: self._serverParams.cwd
      });
      self._process.on('error', (e: Error) => { reject(e); this.onerror?.(e); });
      self._process.on('spawn', () => resolve());
      self._process.on('close', () => { self._process = undefined; this.onclose?.(); });
      self._process.stdin?.on('error', (e: Error) => this.onerror?.(e));
      self._process.stdout?.on('data', (chunk: Buffer) => {
        try { self._readBuffer.append(chunk); self.processReadBuffer(); }
        catch (e) { this.onerror?.(e as Error); this.close().catch(() => {}); }
      });
      self._process.stdout?.on('error', (e: Error) => this.onerror?.(e));
      if (self._stderrStream && self._process.stderr) self._process.stderr.pipe(self._stderrStream);
    });
  }

  async close(): Promise<void> {
    const self = this as any;
    const p = self._process;
    if (!p) return;
    self._process = undefined;
    const closed = new Promise(r => p.once('close', r));
    try { p.stdin?.end(); } catch {}
    await Promise.race([closed, new Promise(r => setTimeout(r, 1000).unref())]);
    for (const sig of ['SIGTERM', 'SIGKILL'] as const) {
      if (p.exitCode !== null) break;
      try { process.kill(-p.pid, sig); } catch {}   // negative pid == whole group
      await Promise.race([closed, new Promise(r => setTimeout(r, 1000).unref())]);
    }
    self._readBuffer.clear();
  }
}
```

~45 LOC, no `tree-kill`. Verified: child gets its own pgid, `tools/list` round-trips, `stderr:'pipe'` still works, and `close()` reaps the grandchild.
